// =================================================================
// STAGE 2: RULE ENGINE (Employment Type + Business Logic)
// =================================================================
// WHAT THIS DOES:
//   The SQL pre-filter checked numeric ranges (income, credit score,
//   age), but it CAN'T easily check if a user's employment_status
//   is in a product's employment_types array. SQL array operations
//   are possible but messy. This Code node handles it cleanly.
//
// WHY NOT IN SQL:
//   Postgres CAN do array containment checks (employment_status = ANY(...)),
//   but mixing it with the JOIN makes the query complex and hard to
//   explain. Separating it into a Code node makes the pipeline clearer
//   and easier to demonstrate.
//
// WHAT IT CHECKS:
//   1. Employment type: Is the user's employment_status in the product's
//      employment_types array? E.g., if a product only accepts 'Salaried'
//      and the user is 'Self-Employed', they're filtered out.
//   2. Credit score margin: How far above the minimum is the user's score?
//      This feeds into the match_score (higher margin = better match).
//
// MATCH SCORE CALCULATION:
//   A value from 0.0 to 1.0 indicating match quality.
//   - 0.5 = baseline (meets all criteria exactly)
//   - +0.25 max for credit score above minimum
//   - +0.25 max for income above minimum
//   Higher score = stronger candidate for the loan.
// =================================================================

const validMatches = [];
let filtered = 0;

for (const item of $input.all()) {
  const data = item.json;

  // --- CHECK 1: Employment Type ---
  // employment_types comes from Postgres as a string like '{Salaried,Self-Employed}'
  // We need to parse it and check if the user's status is included.
  let employmentTypes = data.employment_types;

  // Handle Postgres array format: '{Salaried,Self-Employed}' → ['Salaried', 'Self-Employed']
  if (typeof employmentTypes === 'string') {
    employmentTypes = employmentTypes
      .replace(/[{}]/g, '')  // Remove curly braces
      .split(',')
      .map(t => t.trim());    // Remove whitespace
  }

  // Check if user's employment status matches any accepted type
  if (!employmentTypes.includes(data.employment_status)) {
    filtered++;
    continue; // Skip this pair — employment type doesn't match
  }

  // --- CALCULATE MATCH SCORE ---
  let score = 0.50; // Base score for meeting all criteria

  // Bonus for credit score above minimum (max +0.25)
  const creditMargin = data.credit_score - data.min_credit_score;
  const creditBonus = Math.min(creditMargin / 200, 0.25);
  score += creditBonus;

  // Bonus for income above minimum (max +0.25)
  const incomeMargin = data.monthly_income - data.min_income;
  const incomeBonus = Math.min(incomeMargin / 100000, 0.25);
  score += incomeBonus;

  // Round to 2 decimal places
  score = Math.round(score * 100) / 100;

  // Build a human-readable match reason
  const matchReason = `Meets all criteria: income ₹${data.monthly_income.toLocaleString()} >= min ₹${data.min_income.toLocaleString()}, ` +
    `CIBIL ${data.credit_score} >= min ${data.min_credit_score}, ` +
    `age ${data.age} in range ${data.min_age}-${data.max_age}, ` +
    `employment ${data.employment_status} accepted`;

  validMatches.push({
    json: {
      user_id: data.user_id,
      user_name: data.name,
      user_email: data.email,
      monthly_income: data.monthly_income,
      credit_score: data.credit_score,
      employment_status: data.employment_status,
      age: data.age,
      product_id: data.product_id,
      product_name: data.product_name,
      provider: data.provider,
      interest_rate: data.interest_rate,
      match_score: score,
      match_reason: matchReason
    }
  });
}

console.log(`Stage 2 complete: ${validMatches.length} valid matches, ${filtered} filtered out by employment type`);

// Return the validated matches to the next node
return validMatches;

// =================================================================
// STAGE 3: LLM QUALITATIVE CHECK (Gemini API)
// =================================================================
// WHAT THIS DOES:
//   For the remaining candidates (after SQL + Rule Engine filtering),
//   we use Google's Gemini API to do a final qualitative assessment.
//
// WHY USE AN LLM AT ALL:
//   The task says to 'use an LLM API for specific AI tasks.'
//   The LLM adds value by:
//   1. Generating better, more natural match_reason descriptions
//   2. Catching edge cases our rules might miss
//   3. Assigning a refined confidence score
//
// WHY NOT USE LLM FOR EVERYTHING:
//   This is the key insight for the 'Optimization Treasure Hunt'.
//   With 100K pairs, calling Gemini for each would:
//   - Take ~16 hours (at 0.6s per call)
//   - Cost significant API credits
//   Our pipeline reduces this to ~2K calls (minutes, not hours).
//
// HOW WE BATCH:
//   Instead of one API call per match, we send batches of 10 matches
//   in a single prompt. This is 10x more efficient.
//
// IMPORTANT:
//   You need to set GEMINI_API_KEY as an environment variable in
//   docker-compose.yml, or replace it in this code with your key.
// =================================================================

let GEMINI_API_KEY = '';
try { GEMINI_API_KEY = $env.GEMINI_API_KEY || ''; } catch (e) {}
const BATCH_SIZE = 10; // Process 10 matches per LLM call

// Get all items from the previous node
const allItems = $input.all();
const results = [];

// If no Gemini key, skip LLM step and pass through with existing scores
if (!GEMINI_API_KEY || GEMINI_API_KEY === 'YOUR_GEMINI_API_KEY_HERE') {
  console.log('No Gemini API key set — skipping LLM check, using rule engine scores');
  return allItems;
}

// Process in batches to reduce API calls
for (let i = 0; i < allItems.length; i += BATCH_SIZE) {
  const batch = allItems.slice(i, i + BATCH_SIZE);

  // Build the prompt with batch data
  const matchDescriptions = batch.map((item, idx) => {
    const d = item.json;
    return `Match ${idx + 1}:\n` +
      `  User: ${d.user_name}, Income: ₹${d.monthly_income}/month, ` +
      `CIBIL: ${d.credit_score}, Employment: ${d.employment_status}, Age: ${d.age}\n` +
      `  Product: ${d.product_name} by ${d.provider}, ` +
      `Rate: ${d.interest_rate}%, Min Income: ₹${d.min_income}/month`;
  }).join('\n\n');

  const prompt = `You are a loan eligibility evaluator. For each user-product match below, provide:
1. A confidence score from 0.5 to 1.0 (0.5 = barely eligible, 1.0 = perfect fit)
2. A one-line reason explaining why this is a good/okay match

Respond in JSON format: [{"index": 0, "score": 0.85, "reason": "..."}]

${matchDescriptions}`;

  try {
    // Call Gemini API
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_API_KEY}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: {
            temperature: 0.1,  // Low temperature = more consistent/deterministic
            maxOutputTokens: 1024
          }
        })
      }
    );

    const data = await response.json();
    const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';

    // Parse the JSON response from Gemini
    // Find JSON array in the response (Gemini sometimes wraps it in markdown)
    const jsonMatch = text.match(/\[.*\]/s);
    if (jsonMatch) {
      const llmResults = JSON.parse(jsonMatch[0]);

      // Merge LLM scores and reasons back into our match data
      for (const llmResult of llmResults) {
        const idx = llmResult.index;
        if (idx < batch.length) {
          batch[idx].json.match_score = Math.max(0.5, Math.min(1.0, llmResult.score));
          batch[idx].json.match_reason = llmResult.reason || batch[idx].json.match_reason;
        }
      }
    }
  } catch (error) {
    // If LLM fails, keep the rule engine scores (graceful degradation)
    console.log(`LLM batch ${i / BATCH_SIZE} failed: ${error.message}. Using rule engine scores.`);
  }

  results.push(...batch);
}

console.log(`Stage 3 complete: ${results.length} matches processed through LLM`);
return results.length > 0 ? results : allItems;
